patterns.css:
.dvn {
  --dvn-ink: #16150f;
  --dvn-bone: #f2eee6;
  --dvn-olive: #5b6146;
  --dvn-clay: #b07a5a;
  --dvn-line: rgba(22, 21, 15, .16);
  --dvn-gap: clamp(1rem, 3vw, 2.5rem);
  background: var(--dvn-bone);
  color: var(--dvn-ink);
  font-family: 'Manrope', system-ui, sans-serif;
  line-height: 1.5;
  overflow-x: clip;
}
.dvn *, .dvn *::before, .dvn *::after { box-sizing: border-box; }
.dvn img { max-width: 100%; display: block; }
.dvn-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }

.dvn-head {
  position: sticky;
  top: 0;
  z-index: 30;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: var(--dvn-gap);
  padding: .9rem clamp(1rem, 4vw, 3rem);
  background: color-mix(in srgb, var(--dvn-bone) 88%, transparent);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--dvn-line);
}
.dvn-brand { display: inline-flex; align-items: center; gap: .6rem; color: inherit; text-decoration: none; }
.dvn-brand__mark {
  display: grid;
  place-items: center;
  width: 2.2rem;
  height: 2.2rem;
  border-radius: 50%;
  background: var(--dvn-ink);
  color: var(--dvn-bone);
  font-family: 'Fraunces', Georgia, serif;
  font-size: 1.15rem;
}
.dvn-brand__name { display: flex; flex-direction: column; font-weight: 700; letter-spacing: .02em; line-height: 1; }
.dvn-brand__name small { font-size: .58rem; font-weight: 500; letter-spacing: .22em; text-transform: uppercase; color: var(--dvn-olive); margin-top: .3rem; }
.dvn-nav { display: flex; justify-content: center; gap: clamp(.8rem, 2vw, 1.8rem); font-size: .82rem; letter-spacing: .08em; text-transform: uppercase; }
.dvn-nav a { color: inherit; text-decoration: none; padding: .35rem 0; border-bottom: 1px solid transparent; }
.dvn-nav a:hover, .dvn-nav a:focus-visible { border-color: var(--dvn-ink); }
.dvn-head__actions { display: flex; align-items: center; gap: .75rem; }
.dvn-bag {
  border: 1px solid var(--dvn-ink);
  background: transparent;
  color: inherit;
  border-radius: 999px;
  padding: .45rem .9rem;
  font: inherit;
  font-size: .78rem;
  letter-spacing: .08em;
  text-transform: uppercase;
  cursor: pointer;
}
.dvn-bag span { display: inline-grid; place-items: center; min-width: 1.25rem; height: 1.25rem; margin-left: .35rem; border-radius: 999px; background: var(--dvn-ink); color: var(--dvn-bone); font-size: .7rem; }
.dvn-burger { display: none; width: 2.4rem; height: 2.4rem; border: 1px solid var(--dvn-line); background: transparent; border-radius: 50%; cursor: pointer; }
.dvn-burger span { display: block; width: 1rem; height: 1px; margin: .28rem auto; background: var(--dvn-ink); transition: transform .25s ease; }
.dvn-burger[aria-expanded="true"] span:first-child { transform: translateY(3px) rotate(45deg); }
.dvn-burger[aria-expanded="true"] span:last-child { transform: translateY(-3px) rotate(-45deg); }
.dvn-drawer {
  position: fixed;
  inset: 3.6rem 0 auto;
  z-index: 29;
  display: grid;
  gap: .25rem;
  padding: 1.25rem clamp(1rem, 4vw, 3rem) 2rem;
  background: var(--dvn-bone);
  border-bottom: 1px solid var(--dvn-line);
}
.dvn-drawer a { color: inherit; text-decoration: none; font-size: 1.4rem; font-family: 'Fraunces', Georgia, serif; padding: .35rem 0; }

.dvn-ticker { overflow: hidden; border-bottom: 1px solid var(--dvn-line); background: var(--dvn-ink); color: var(--dvn-bone); }
.dvn-ticker__track { display: flex; gap: 2.5rem; width: max-content; padding: .55rem 0; font-size: .72rem; letter-spacing: .18em; text-transform: uppercase; animation: dvn-run 26s linear infinite; }
.dvn-ticker__track span { white-space: nowrap; }
@keyframes dvn-run { to { transform: translateX(-50%); } }

.dvn-main { padding: 0 clamp(1rem, 4vw, 3rem); }
.dvn-kicker { margin: 0 0 1rem; font-size: .72rem; letter-spacing: .22em; text-transform: uppercase; color: var(--dvn-olive); }
.dvn-h2 { margin: 0; font-family: 'Fraunces', Georgia, serif; font-weight: 500; font-size: clamp(1.8rem, 3.4vw, 2.9rem); letter-spacing: -.02em; }
.dvn-note { margin: .5rem 0 0; max-width: 34ch; color: color-mix(in srgb, var(--dvn-ink) 70%, var(--dvn-bone)); }
.dvn-link { color: inherit; font-size: .8rem; letter-spacing: .1em; text-transform: uppercase; text-decoration: none; border-bottom: 1px solid var(--dvn-ink); padding-bottom: .15rem; }
.dvn-section-head { display: flex; align-items: flex-end; justify-content: space-between; gap: var(--dvn-gap); margin-bottom: clamp(1.2rem, 3vw, 2.4rem); }
.dvn-section-head--inline { align-items: center; }

.dvn-stage {
  display: grid;
  grid-template-columns: minmax(0, .9fr) minmax(0, 1.1fr);
  grid-template-areas: "copy collage";
  align-items: center;
  gap: clamp(1.5rem, 5vw, 4rem);
  padding: clamp(2.5rem, 7vw, 6rem) 0 clamp(2rem, 5vw, 4rem);
}
.dvn-stage__copy { grid-area: copy; max-width: 34rem; }
.dvn-title { margin: 0 0 1.25rem; font-family: 'Fraunces', Georgia, serif; font-weight: 400; font-size: clamp(3rem, 8vw, 6.5rem); line-height: .9; letter-spacing: -.04em; }
.dvn-title em { font-style: italic; color: var(--dvn-clay); }
.dvn-lede { margin: 0 0 1.75rem; max-width: 32ch; font-size: clamp(1rem, 1.4vw, 1.12rem); color: color-mix(in srgb, var(--dvn-ink) 78%, var(--dvn-bone)); }
.dvn-row { display: flex; flex-wrap: wrap; gap: .75rem; }
.dvn-btn { display: inline-flex; align-items: center; justify-content: center; padding: .85rem 1.5rem; border-radius: 999px; font-size: .78rem; letter-spacing: .12em; text-transform: uppercase; text-decoration: none; border: 1px solid var(--dvn-ink); cursor: pointer; font-family: inherit; }
.dvn-btn--ink { background: var(--dvn-ink); color: var(--dvn-bone); }
.dvn-btn--ghost { background: transparent; color: var(--dvn-ink); }
.dvn-btn:hover { transform: translateY(-1px); }

.dvn-collage {
  grid-area: collage;
  position: relative;
  display: grid;
  grid-template-columns: 1.2fr .8fr;
  grid-template-rows: repeat(6, 1fr);
  gap: .75rem;
  margin: 0;
  min-height: clamp(24rem, 52vw, 38rem);
}
.dvn-collage__tall {
  grid-column: 1;
  grid-row: 1 / span 6;
  background: linear-gradient(160deg, #d9d2c2 0%, #c2b9a4 55%, #8f866f 100%);
  clip-path: polygon(0 4%, 100% 0, 100% 96%, 0 100%);
}
.dvn-collage__wide {
  grid-column: 2;
  grid-row: 2 / span 3;
  background: linear-gradient(200deg, #6f7558 0%, #4c5239 100%);
}
.dvn-vertical {
  position: absolute;
  right: -.25rem;
  bottom: 0;
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  font-size: .66rem;
  letter-spacing: .24em;
  text-transform: uppercase;
  color: var(--dvn-olive);
}

.dvn-index { padding: clamp(2.5rem, 6vw, 5rem) 0; border-top: 1px solid var(--dvn-line); }
.dvn-index__list { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--dvn-line); }
.dvn-index__list li { border-bottom: 1px solid var(--dvn-line); }
.dvn-index__list a { display: grid; grid-template-columns: 4rem 1fr auto; align-items: baseline; gap: 1rem; padding: clamp(.9rem, 2vw, 1.4rem) 0; color: inherit; text-decoration: none; transition: padding-left .25s ease, color .25s ease; }
.dvn-index__list a:hover, .dvn-index__list a:focus-visible { padding-left: .75rem; color: var(--dvn-olive); }
.dvn-index__n { font-size: .72rem; letter-spacing: .16em; color: var(--dvn-clay); }
.dvn-index__name { font-family: 'Fraunces', Georgia, serif; font-size: clamp(1.4rem, 3vw, 2.2rem); letter-spacing: -.01em; }
.dvn-index__meta { font-size: .74rem; letter-spacing: .12em; text-transform: uppercase; color: var(--dvn-olive); }

.dvn-runway { padding: clamp(2.5rem, 6vw, 5rem) 0; border-top: 1px solid var(--dvn-line); }
.dvn-runway__rail { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(15rem, 22rem); gap: var(--dvn-gap); overflow-x: auto; padding-bottom: 1rem; scroll-snap-type: x mandatory; scrollbar-width: thin; }
.dvn-card { scroll-snap-align: start; display: flex; flex-direction: column; gap: .9rem; }
.dvn-card__media { aspect-ratio: 3 / 4; border-radius: 2px; }
.dvn-card__media--a { background: linear-gradient(150deg, #e3dccd, #b8ad94); }
.dvn-card__media--b { background: linear-gradient(150deg, #8a9070, #4e5539); }
.dvn-card__media--c { background: linear-gradient(150deg, #b9a99c, #7a6558); }
.dvn-card__media--d { background: linear-gradient(150deg, #d5d2cd, #9a968e); }
.dvn-card__body h3 { margin: 0; font-size: .95rem; font-weight: 600; }
.dvn-price { margin: .15rem 0 .6rem; font-size: .85rem; color: var(--dvn-olive); }
.dvn-add { align-self: flex-start; background: none; border: 0; border-bottom: 1px solid var(--dvn-ink); padding: 0 0 .15rem; font: inherit; font-size: .72rem; letter-spacing: .1em; text-transform: uppercase; cursor: pointer; }

.dvn-lookbook { padding: clamp(2.5rem, 6vw, 5rem) 0; border-top: 1px solid var(--dvn-line); }
.dvn-lookbook__grid { display: grid; grid-template-columns: repeat(12, 1fr); gap: var(--dvn-gap); }
.dvn-look { margin: 0; position: relative; display: flex; align-items: flex-end; min-height: clamp(16rem, 30vw, 26rem); }
.dvn-look figcaption { position: relative; z-index: 1; padding: .75rem 1rem; font-size: .72rem; letter-spacing: .12em; text-transform: uppercase; color: var(--dvn-bone); }
.dvn-look--one { grid-column: 1 / span 7; background: linear-gradient(180deg, #c9c2b1, #6f6a59); }
.dvn-look--two { grid-column: 8 / span 5; background: linear-gradient(180deg, #7d8367, #3f452e); margin-top: clamp(1.5rem, 4vw, 3rem); }
.dvn-look--three { grid-column: 3 / span 8; background: linear-gradient(180deg, #b58f76, #6d4c3b); margin-top: calc(var(--dvn-gap) * -0.5); }

.dvn-manifesto { display: grid; grid-template-columns: minmax(0, .8fr) minmax(0, 1.2fr); gap: clamp(1.5rem, 5vw, 4rem); padding: clamp(3rem, 7vw, 6rem) 0; border-top: 1px solid var(--dvn-line); }
.dvn-manifesto__side { position: relative; }
.dvn-manifesto__sticky { position: sticky; top: 6rem; margin: 0; font-family: 'Fraunces', Georgia, serif; font-size: clamp(1.35rem, 2.4vw, 1.9rem); line-height: 1.25; letter-spacing: -.01em; }
.dvn-manifesto__body p { margin: 0 0 2rem; max-width: 46ch; color: color-mix(in srgb, var(--dvn-ink) 80%, var(--dvn-bone)); }
.dvn-facts { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1rem; margin: 0; padding-top: 1.5rem; border-top: 1px solid var(--dvn-line); }
.dvn-facts dt { font-family: 'Fraunces', Georgia, serif; font-size: clamp(1.6rem, 3vw, 2.4rem); }
.dvn-facts dd { margin: .2rem 0 0; font-size: .74rem; letter-spacing: .1em; text-transform: uppercase; color: var(--dvn-olive); }

.dvn-service { padding: clamp(2.5rem, 6vw, 5rem) 0; border-top: 1px solid var(--dvn-line); }
.dvn-service__steps { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--dvn-gap); }
.dvn-service__steps li { padding-top: 1.25rem; border-top: 2px solid var(--dvn-ink); }
.dvn-service__steps span { font-size: .72rem; letter-spacing: .16em; color: var(--dvn-clay); }
.dvn-service__steps h3 { margin: .6rem 0 .4rem; font-family: 'Fraunces', Georgia, serif; font-weight: 500; font-size: 1.4rem; }
.dvn-service__steps p { margin: 0; max-width: 28ch; font-size: .92rem; color: color-mix(in srgb, var(--dvn-ink) 76%, var(--dvn-bone)); }

.dvn-news { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); align-items: end; gap: var(--dvn-gap); padding: clamp(2.5rem, 6vw, 5rem) 0; border-top: 1px solid var(--dvn-line); }
.dvn-news__form { display: flex; gap: .6rem; flex-wrap: wrap; }
.dvn-news__form input { flex: 1 1 12rem; min-width: 0; padding: .85rem 1rem; border: 1px solid var(--dvn-line); background: transparent; color: inherit; font: inherit; border-radius: 999px; }
.dvn-news__form input:focus-visible { outline: 2px solid var(--dvn-olive); outline-offset: 2px; }

.dvn-foot { display: flex; flex-wrap: wrap; justify-content: space-between; gap: .5rem; padding: 1.5rem clamp(1rem, 4vw, 3rem); border-top: 1px solid var(--dvn-line); font-size: .72rem; letter-spacing: .1em; text-transform: uppercase; color: var(--dvn-olive); }
.dvn-foot p { margin: 0; }

@media (max-width: 860px) {
  .dvn-nav { display: none; }
  .dvn-burger { display: block; }
  .dvn-stage { grid-template-columns: 1fr; grid-template-areas: "copy" "collage"; }
  .dvn-collage { min-height: 26rem; }
  .dvn-manifesto, .dvn-news { grid-template-columns: 1fr; }
  .dvn-manifesto__sticky { position: static; }
  .dvn-service__steps { grid-template-columns: 1fr; }
  .dvn-look--one, .dvn-look--two, .dvn-look--three { grid-column: 1 / -1; margin-top: 0; }
  .dvn-facts { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (prefers-reduced-motion: reduce) {
  .dvn-ticker__track { animation: none; }
  .dvn-index__list a, .dvn-btn { transition: none; }
}

patterns.js:
(function () {
  var root = document.querySelector('[data-pattern="daven-indumentaria"]');
  if (!root) return;

  var burger = root.querySelector('[data-dvn-burger]');
  var drawer = root.querySelector('[data-dvn-drawer]');
  if (burger && drawer) {
    burger.addEventListener('click', function () {
      var open = burger.getAttribute('aria-expanded') === 'true';
      burger.setAttribute('aria-expanded', String(!open));
      drawer.hidden = open;
    });
    drawer.addEventListener('click', function (event) {
      if (event.target.tagName === 'A') {
        burger.setAttribute('aria-expanded', 'false');
        drawer.hidden = true;
      }
    });
  }

  var track = root.querySelector('[data-dvn-track]');
  if (track) track.innerHTML += track.innerHTML;

  var count = root.querySelector('[data-dvn-count]');
  root.querySelectorAll('[data-dvn-add]').forEach(function (button) {
    button.addEventListener('click', function () {
      if (!count) return;
      count.textContent = String(Number(count.textContent || 0) + 1);
    });
  });

  var rail = root.querySelector('[data-dvn-rail]');
  if (rail) {
    rail.addEventListener('keydown', function (event) {
      if (event.key !== 'ArrowRight' && event.key !== 'ArrowLeft') return;
      event.preventDefault();
      rail.scrollBy({ left: (event.key === 'ArrowRight' ? 1 : -1) * rail.clientWidth * 0.8, behavior: 'smooth' });
    });
  }

  var form = root.querySelector('.dvn-news__form');
  if (form) {
    form.addEventListener('submit', function (event) {
      event.preventDefault();
      var input = form.querySelector('input[type="email"]');
      if (input && input.checkValidity()) form.reset();
    });
  }
})();

patterns.css:
/* Patrón inspirado en Mercado Libre: barra amarilla, búsqueda blanca,
   acento azul de marketplace, grilla densa de productos con cuotas,
   envío gratis y descuentos. */
:root{
  --ml-yellow:#FFE600;
  --ml-blue:#3483FA;
  --ml-blue-dark:#2968C8;
  --ml-green:#00A650;
  --ml-bg:#EBEBEB;
  --ml-surface:#FFFFFF;
  --ml-ink:#333333;
  --ml-muted:#666666;
  --ml-line:#E0E0E0;
  --ml-radius:8px;
  --ml-font:"Figtree", "Helvetica Neue", Arial, sans-serif;
  --ml-display:"Archivo", "Helvetica Neue", Arial, sans-serif;
  color-scheme: light;
}
*{box-sizing:border-box}
html,body{margin:0}
body{
  background:var(--ml-bg);
  color:var(--ml-ink);
  font:15px/1.45 var(--ml-font);
  -webkit-font-smoothing:antialiased;
}
img{max-width:100%}
button{font:inherit;color:inherit;cursor:pointer}
a{color:inherit;text-decoration:none}
:focus-visible{outline:2px solid var(--ml-blue);outline-offset:2px}
.ml-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}

/* HEADER */
.ml-top{background:var(--ml-yellow)}
.ml-top__bar{
  max-width:1200px;margin:0 auto;
  display:grid;grid-template-columns:auto 1fr auto;align-items:center;
  gap:24px;padding:12px 20px 10px;
}
.ml-brand{display:flex;align-items:center;gap:10px;font:800 22px/1 var(--ml-display);letter-spacing:-.02em}
.ml-brand__mark{
  width:34px;height:34px;border-radius:50%;
  background:var(--ml-blue);color:#fff;
  display:grid;place-items:center;font-size:16px;font-weight:800;
}
.ml-brand small{display:block;font:600 10px/1 var(--ml-font);letter-spacing:.16em;text-transform:uppercase;color:#4a4300;margin-top:3px}
.ml-search{display:flex;align-items:center;gap:8px;background:#fff;border-radius:4px;padding:0 12px;height:42px;box-shadow:0 1px 2px rgba(0,0,0,.12)}
.ml-search input{border:0;outline:0;flex:1;font:inherit;background:transparent;color:var(--ml-ink)}
.ml-search button{border:0;background:transparent;display:grid;place-items:center;padding:4px}
.ml-search svg{width:20px;height:20px;stroke:#8a8a8a;fill:none;stroke-width:2}
.ml-top__actions{display:flex;align-items:center;gap:18px;font-size:13px;font-weight:600}
.ml-cart{display:flex;align-items:center;gap:7px;border:0;background:transparent}
.ml-cart svg{width:22px;height:22px;fill:none;stroke:var(--ml-ink);stroke-width:1.8}
.ml-cart span{min-width:20px;height:20px;border-radius:999px;background:var(--ml-blue);color:#fff;font-size:11px;display:grid;place-items:center;padding:0 5px}
.ml-nav{background:#fff;border-bottom:1px solid var(--ml-line)}
.ml-nav__inner{max-width:1200px;margin:0 auto;display:flex;gap:26px;padding:10px 20px;overflow-x:auto;font-size:13px;color:#555;white-space:nowrap}
.ml-nav a:hover{color:var(--ml-blue)}

/* WRAP */
.ml-wrap{max-width:1200px;margin:0 auto;padding:0 20px 72px}
.ml-strip{
  display:flex;align-items:center;justify-content:center;gap:10px;
  background:#fff;border-radius:0 0 var(--ml-radius) var(--ml-radius);
  padding:10px 16px;font-size:13px;font-weight:600;color:#1f5f3f;
}
.ml-strip svg{width:18px;height:18px;stroke:var(--ml-green);fill:none;stroke-width:1.8}

/* HERO */
.ml-hero{
  margin-top:16px;display:grid;grid-template-columns:1.05fr .95fr;
  gap:0;background:linear-gradient(120deg,#1b4f9c,#3483FA 62%,#5aa0ff);
  border-radius:var(--ml-radius);overflow:hidden;color:#fff;
}
.ml-hero__copy{padding:clamp(22px,4vw,48px);display:flex;flex-direction:column;justify-content:center;gap:14px}
.ml-hero__eyebrow{font:700 12px/1 var(--ml-font);letter-spacing:.14em;text-transform:uppercase;color:#FFE600}
.ml-hero h1{margin:0;font:800 clamp(28px,4vw,46px)/1.05 var(--ml-display);letter-spacing:-.02em}
.ml-hero p{margin:0;max-width:38ch;color:#e6efff;font-size:15px}
.ml-hero__cta{align-self:flex-start;margin-top:8px;background:var(--ml-yellow);color:#2b2a00;border:0;border-radius:6px;padding:13px 24px;font-weight:800;font-size:14px}
.ml-hero__cta:hover{background:#ffe93a}
.ml-hero__art{position:relative;min-height:260px;background:
  radial-gradient(120px 120px at 68% 32%,rgba(255,255,255,.35),transparent 70%),
  radial-gradient(220px 220px at 30% 80%,rgba(0,0,0,.18),transparent 70%);}
.ml-hero__art i{position:absolute;display:block;background:rgba(255,255,255,.9);border-radius:10px;box-shadow:0 18px 40px rgba(0,0,0,.18)}
.ml-hero__art i:nth-child(1){width:44%;height:52%;left:12%;top:22%;transform:rotate(-7deg);background:linear-gradient(160deg,#fff,#dfe9fb)}
.ml-hero__art i:nth-child(2){width:36%;height:44%;right:10%;top:12%;transform:rotate(6deg);background:linear-gradient(160deg,#FFE600,#ffd000)}
.ml-hero__art i:nth-child(3){width:30%;height:26%;right:18%;bottom:12%;transform:rotate(-3deg);background:linear-gradient(160deg,#fff,#cfe0ff)}
.ml-hero__art b{
  position:absolute;left:10%;bottom:10%;background:#00A650;color:#fff;
  font:800 13px/1 var(--ml-font);padding:8px 12px;border-radius:999px;transform:rotate(-3deg);
}

/* CATEGORIAS */
.ml-cats{display:grid;grid-template-columns:repeat(7,1fr);gap:10px;margin-top:16px;background:#fff;border-radius:var(--ml-radius);padding:16px 12px}
.ml-cat{display:flex;flex-direction:column;align-items:center;gap:9px;border:0;background:transparent;padding:4px;border-radius:8px}
.ml-cat:hover{background:#f5f5f5}
.ml-cat__icon{width:54px;height:54px;border-radius:50%;display:grid;place-items:center;background:#eef4ff;color:var(--ml-blue)}
.ml-cat:nth-child(2n) .ml-cat__icon{background:#fff6cc;color:#8a7600}
.ml-cat:nth-child(3n) .ml-cat__icon{background:#e9f8ef;color:#00803d}
.ml-cat__icon svg{width:26px;height:26px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}
.ml-cat span{font-size:12px;color:#444;text-align:center}

/* SECCIONES */
.ml-section{margin-top:26px}
.ml-section__head{display:flex;align-items:baseline;justify-content:space-between;gap:16px;margin-bottom:12px}
.ml-section__head h2{margin:0;font:800 21px/1.2 var(--ml-display);letter-spacing:-.01em}
.ml-section__head a{color:var(--ml-blue);font-size:13px;font-weight:700}

/* OFERTAS */
.ml-offers{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.ml-offer{background:#fff;border-radius:var(--ml-radius);overflow:hidden;display:flex;flex-direction:column;box-shadow:0 1px 2px rgba(0,0,0,.08)}
.ml-offer__media{position:relative;aspect-ratio:16/10;background:linear-gradient(150deg,#eef2f8,#dbe6f7);display:grid;place-items:center}
.ml-offer:nth-child(2) .ml-offer__media{background:linear-gradient(150deg,#fff8d6,#ffeaa0)}
.ml-offer:nth-child(3) .ml-offer__media{background:linear-gradient(150deg,#e8f8ee,#c9efd8)}
.ml-offer:nth-child(4) .ml-offer__media{background:linear-gradient(150deg,#fdeceb,#f9d6d3)}
.ml-offer__media svg{width:54px;height:54px;stroke:#5b6b82;fill:none;stroke-width:1.4}
.ml-offer__badge{position:absolute;left:10px;top:10px;background:var(--ml-green);color:#fff;font:800 12px/1 var(--ml-font);padding:6px 8px;border-radius:4px}
.ml-offer__body{padding:12px 14px 16px;display:flex;flex-direction:column;gap:4px}
.ml-offer__title{font-size:14px;color:#333;margin:0}
.ml-offer__old{margin:0;font-size:12px;color:#999;text-decoration:line-through}
.ml-offer__price{margin:0;font:800 22px/1.1 var(--ml-display);color:#111}
.ml-offer__inst{margin:0;font-size:12px;color:var(--ml-green);font-weight:600}
.ml-offer__ship{margin:0;font-size:12px;color:var(--ml-green);font-weight:700}

/* BENEFICIOS */
.ml-benefits{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:26px}
.ml-benefit{background:#fff;border-radius:var(--ml-radius);padding:16px;display:flex;gap:12px;align-items:flex-start}
.ml-benefit svg{width:26px;height:26px;flex:none;stroke:var(--ml-blue);fill:none;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}
.ml-benefit strong{display:block;font-size:14px;margin-bottom:2px}
.ml-benefit span{font-size:12px;color:var(--ml-muted);line-height:1.35}

/* GRILLA DE PRODUCTOS */
.ml-toolbar{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-top:26px;flex-wrap:wrap}
.ml-chips{display:flex;gap:8px;flex-wrap:wrap}
.ml-chip{border:1px solid var(--ml-line);background:#fff;border-radius:999px;padding:7px 14px;font-size:13px;color:#444}
.ml-chip[aria-pressed="true"]{background:#e6efff;border-color:#b9d2fb;color:var(--ml-blue-dark);font-weight:700}
.ml-sort{border:1px solid var(--ml-line);background:#fff;border-radius:6px;padding:8px 10px;font-size:13px;color:#444}
.ml-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:12px}
.ml-card{background:#fff;border-radius:var(--ml-radius);padding:14px;display:flex;flex-direction:column;gap:6px;box-shadow:0 1px 2px rgba(0,0,0,.08);transition:box-shadow .18s ease,transform .18s ease}
.ml-card:hover{box-shadow:0 8px 22px rgba(0,0,0,.12);transform:translateY(-2px)}
.ml-card__media{aspect-ratio:1/1;border-radius:6px;background:linear-gradient(150deg,#f4f6fa,#e3ebf7);display:grid;place-items:center;margin-bottom:6px}
.ml-card__media svg{width:58px;height:58px;stroke:#7a8798;fill:none;stroke-width:1.3}
.ml-card__tag{margin:0;font-size:11px;font-weight:700;color:var(--ml-green);text-transform:uppercase;letter-spacing:.06em}
.ml-card__title{margin:0;font-size:14px;font-weight:500;color:#333;line-height:1.35}
.ml-card__price{margin:2px 0 0;font:800 20px/1.1 var(--ml-display);color:#111}
.ml-card__inst{margin:0;font-size:12px;color:var(--ml-green);font-weight:600}
.ml-card__ship{margin:0;font-size:12px;color:var(--ml-green);font-weight:700}
.ml-card__add{margin-top:8px;border:0;border-radius:6px;background:var(--ml-blue);color:#fff;font-weight:700;font-size:13px;padding:10px}
.ml-card__add:hover{background:var(--ml-blue-dark)}
.ml-empty{margin-top:14px;background:#fff;border-radius:var(--ml-radius);padding:28px;text-align:center;color:var(--ml-muted);display:none}

/* MARCAS */
.ml-brands{display:grid;grid-template-columns:repeat(6,1fr);gap:10px;margin-top:26px}
.ml-brandcard{background:#fff;border-radius:var(--ml-radius);padding:18px 10px;text-align:center;font:800 14px/1 var(--ml-display);color:#8a93a3;letter-spacing:.02em}

/* FAQ */
.ml-faq{margin-top:26px;background:#fff;border-radius:var(--ml-radius);padding:6px 20px}
.ml-faq details{border-bottom:1px solid var(--ml-line);padding:14px 0}
.ml-faq details:last-child{border-bottom:0}
.ml-faq summary{cursor:pointer;font-weight:700;font-size:14px;list-style:none;display:flex;justify-content:space-between;gap:12px}
.ml-faq summary::-webkit-details-marker{display:none}
.ml-faq summary::after{content:"+";color:var(--ml-blue);font-weight:800}
.ml-faq details[open] summary::after{content:"–"}
.ml-faq p{margin:8px 0 0;color:var(--ml-muted);font-size:13px;line-height:1.5}

/* CTA + FOOTER */
.ml-cta{margin-top:26px;background:linear-gradient(110deg,#1b4f9c,#3483FA);border-radius:var(--ml-radius);color:#fff;padding:clamp(22px,3.4vw,40px);display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap}
.ml-cta h2{margin:0;font:800 clamp(22px,3vw,30px)/1.15 var(--ml-display)}
.ml-cta p{margin:6px 0 0;color:#dce8ff;font-size:14px}
.ml-cta button{border:0;border-radius:6px;background:var(--ml-yellow);color:#2b2a00;font-weight:800;padding:13px 24px}
.ml-foot{margin-top:26px;background:#fff;border-radius:var(--ml-radius);padding:26px 20px;display:grid;grid-template-columns:repeat(4,1fr);gap:20px;font-size:13px}
.ml-foot h3{margin:0 0 8px;font-size:13px;text-transform:uppercase;letter-spacing:.08em;color:#777}
.ml-foot a{display:block;color:#555;padding:3px 0}
.ml-foot a:hover{color:var(--ml-blue)}
.ml-foot__legal{grid-column:1/-1;border-top:1px solid var(--ml-line);padding-top:14px;color:#8a8a8a;font-size:12px}

/* RESPONSIVE */
@media (max-width:980px){
  .ml-grid,.ml-offers{grid-template-columns:repeat(3,1fr)}
  .ml-cats{grid-template-columns:repeat(4,1fr)}
  .ml-benefits{grid-template-columns:repeat(2,1fr)}
  .ml-brands{grid-template-columns:repeat(3,1fr)}
}
@media (max-width:720px){
  .ml-top__bar{grid-template-columns:auto 1fr;gap:12px}
  .ml-top__actions{display:none}
  .ml-hero{grid-template-columns:1fr}
  .ml-hero__art{min-height:190px}
  .ml-grid,.ml-offers{grid-template-columns:repeat(2,1fr)}
  .ml-cats{grid-template-columns:repeat(4,1fr);gap:4px}
  .ml-cat__icon{width:46px;height:46px}
  .ml-foot{grid-template-columns:repeat(2,1fr)}
}
@media (max-width:420px){
  .ml-grid,.ml-offers{grid-template-columns:1fr}
  .ml-wrap{padding:0 12px 56px}
}
@media (prefers-reduced-motion:reduce){
  *{transition:none!important;animation:none!important}
}

patterns.js:
(function () {
  var root = document.querySelector('[data-pattern="mercado-libre"]');
  if (!root) return;

  var grid = root.querySelector('[data-ml-grid]');
  var cards = Array.prototype.slice.call(root.querySelectorAll('[data-ml-card]'));
  var empty = root.querySelector('[data-ml-empty]');
  var query = root.querySelector('[data-ml-q]');
  var form = root.querySelector('[data-ml-search]');
  var order = root.querySelector('[data-ml-order]');
  var count = root.querySelector('[data-ml-count]');
  var chips = Array.prototype.slice.call(root.querySelectorAll('[data-ml-filter]'));
  var activeCat = 'todos';
  var term = '';

  function render() {
    var visible = 0;
    cards.forEach(function (card) {
      var name = (card.getAttribute('data-name') || '').toLowerCase();
      var cat = card.getAttribute('data-cat') || '';
      var matchCat = activeCat === 'todos' || cat === activeCat;
      var matchTerm = !term || name.indexOf(term) !== -1;
      var show = matchCat && matchTerm;
      card.hidden = !show;
      if (show) visible++;
    });
    if (empty) empty.style.display = visible ? 'none' : 'block';
  }

  function sortCards() {
    var mode = order ? order.value : 'relevancia';
    if (mode === 'relevancia' || !grid) return;
    var sorted = cards.slice().sort(function (a, b) {
      var pa = Number(a.getAttribute('data-price')) || 0;
      var pb = Number(b.getAttribute('data-price')) || 0;
      return mode === 'menor' ? pa - pb : pb - pa;
    });
    sorted.forEach(function (card) { grid.appendChild(card); });
  }

  if (form) {
    form.addEventListener('submit', function (event) {
      event.preventDefault();
      term = (query && query.value || '').trim().toLowerCase();
      render();
    });
  }
  if (query) {
    query.addEventListener('input', function () {
      term = query.value.trim().toLowerCase();
      render();
    });
  }
  if (order) order.addEventListener('change', function () { sortCards(); render(); });

  chips.forEach(function (chip) {
    chip.addEventListener('click', function () {
      activeCat = chip.getAttribute('data-ml-filter') || 'todos';
      chips.forEach(function (other) {
        other.setAttribute('aria-pressed', other === chip ? 'true' : 'false');
      });
      render();
    });
  });

  root.querySelectorAll('[data-ml-cat]').forEach(function (button) {
    button.addEventListener('click', function () {
      var cat = button.getAttribute('data-ml-cat');
      var chip = chips.filter(function (c) { return c.getAttribute('data-ml-filter') === cat; })[0];
      if (chip) chip.click();
      else { activeCat = cat; render(); }
      if (grid) grid.scrollIntoView({ behavior: 'smooth', block: 'start' });
    });
  });

  var total = 0;
  root.querySelectorAll('[data-ml-add]').forEach(function (button) {
    button.addEventListener('click', function () {
      total++;
      if (count) count.textContent = String(total);
      button.textContent = 'Agregado';
      setTimeout(function () { button.textContent = 'Agregar al carrito'; }, 1400);
    });
  });

  render();
})();

patterns.css:
@import url('https://fonts.googleapis.com/css2?family=Newsreader:ital,opsz,wght@0,6..72,400;0,6..72,500;0,6..72,600;1,6..72,400&family=Manrope:wght@400;500;600;700&family=Space+Mono:wght@400;700&display=swap');

/* Aula Abierta — landing de educación.
   Idea: la página es un cuaderno de cátedra. Papel con renglones y margen
   rojo, índice numerado en el canto, hero partido con horario, banda
   diagonal de materias, programa como lista editorial (no tarjetas),
   pasos con numerales gigantes, docentes en tira de retratos duotono,
   cita con comilla de agua y admisión como libro contable. */

:root{
  --paper:#F5F1E6;
  --paper-2:#EDE7D7;
  --surface:#FFFDF7;
  --ink:#101827;
  --ink-2:#39465A;
  --muted:#6B7385;
  --line:#D3C9B4;
  --line-2:#BEB29A;
  --red:#C93F26;
  --red-soft:#F4DCD4;
  --blue:#173A63;
  --blue-soft:#DDE5EF;
  --gold:#B98B3C;
  --on-red:#FFF6F1;
  --display:"Newsreader","Iowan Old Style",Georgia,serif;
  --body:"Manrope",system-ui,-apple-system,"Segoe UI",sans-serif;
  --mono:"Space Mono",ui-monospace,"SFMono-Regular",monospace;
  --rule:1px;
  --radius:2px;
  --shadow:0 1px 0 rgba(16,24,39,.06), 0 26px 50px -40px rgba(16,24,39,.55);
  --maxw:1180px;
  color-scheme: light;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
html,body{margin:0}
body{
  background:var(--paper);
  color:var(--ink);
  font:16px/1.62 var(--body);
  -webkit-font-smoothing:antialiased;
  overflow-x:hidden;
}
/* renglones de cuaderno + grano de papel */
body::before{
  content:"";position:fixed;inset:0;z-index:-1;pointer-events:none;
  background:
    repeating-linear-gradient(to bottom, transparent 0 31px, rgba(23,58,99,.055) 31px 32px),
    radial-gradient(120% 80% at 12% 0%, rgba(255,255,255,.7), transparent 60%),
    repeating-linear-gradient(94deg, rgba(16,24,39,.022) 0 1px, transparent 1px 4px);
}
img,svg{max-width:100%}
a{color:inherit;text-decoration:none}
button,input,select{font:inherit;color:inherit}
button{background:none;border:0;cursor:pointer}
h1,h2,h3,h4{margin:0;font-family:var(--display);font-weight:500;letter-spacing:-.022em;text-wrap:balance}
h1{font-size:clamp(2.55rem,6.2vw,5.2rem);line-height:.98}
h2{font-size:clamp(1.85rem,3.5vw,2.9rem);line-height:1.04}
h3{font-size:1.16rem;line-height:1.3;font-weight:600;letter-spacing:-.01em}
p{margin:0}
:focus-visible{outline:2px solid var(--red);outline-offset:3px}
.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.i{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round;flex:none}

/* ---------- retícula base ---------- */
.wrap{width:min(var(--maxw),100% - 40px);margin-inline:auto;position:relative}
.shell{
  display:grid;grid-template-columns:76px minmax(0,1fr);
  width:min(var(--maxw),100% - 40px);margin-inline:auto;
}
.shell > .main{min-width:0}
.eyebrow{
  display:inline-flex;align-items:center;gap:9px;margin:0 0 16px;
  font:400 .68rem/1 var(--mono);letter-spacing:.18em;text-transform:uppercase;color:var(--red);
}
.eyebrow::before{content:"";width:24px;height:var(--rule);background:currentColor;opacity:.7}
.lede{color:var(--ink-2);font-size:1.03rem;max-width:44ch}

/* ---------- barra superior ---------- */
.top{
  position:sticky;top:0;z-index:40;
  background:color-mix(in srgb,var(--paper) 92%,transparent);
  backdrop-filter:blur(8px);
  border-bottom:var(--rule) solid var(--line);
}
.top-in{display:flex;align-items:center;gap:20px;padding-block:13px}
.brand{display:inline-flex;align-items:center;gap:10px;min-height:44px;font-family:var(--display);font-size:1.24rem;letter-spacing:-.03em}
.brand svg{width:26px;height:26px;color:var(--red)}
.brand b{font-weight:600}
.nav{display:none;gap:24px;margin-inline:auto;font-size:.86rem;color:var(--ink-2)}
.nav a{position:relative;padding-block:6px;transition:color .18s}
.nav a:hover{color:var(--red)}
.nav a::after{content:"";position:absolute;left:0;right:0;bottom:0;height:var(--rule);background:var(--red);transform:scaleX(0);transform-origin:left;transition:transform .28s ease}
.nav a:hover::after{transform:scaleX(1)}
.btn{
  display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:44px;
  padding:0 20px;border:var(--rule) solid var(--ink);border-radius:var(--radius);
  font:600 .84rem/1 var(--body);letter-spacing:.01em;
  transition:background .18s, color .18s, border-color .18s, transform .18s;
}
.btn:hover{transform:translateY(-1px)}
.btn-solid{background:var(--red);border-color:var(--red);color:var(--on-red)}
.btn-solid:hover{background:var(--ink);border-color:var(--ink)}
.btn-ghost{background:transparent;color:var(--ink)}
.btn-ghost:hover{background:var(--ink);color:var(--paper)}
.btn .i{transition:transform .22s}
.btn:hover .i{transform:translateX(3px)}
.top-cta{display:none}
.menu-btn{display:inline-flex;align-items:center;justify-content:center;width:44px;height:44px;margin-left:auto;border:var(--rule) solid var(--line-2);border-radius:var(--radius)}
.menu-btn:hover{border-color:var(--ink)}
.menu{display:grid;gap:2px;padding-bottom:14px}
.menu[hidden]{display:none}
.menu a{padding:11px 0;border-top:var(--rule) solid var(--line);font-size:.9rem}

/* ---------- índice del canto ---------- */
.rail{
  display:none;position:sticky;top:0;height:100vh;
  padding-top:74px;border-right:var(--rule) solid var(--line);
}
.rail ol{list-style:none;margin:0;padding:0 0 0 18px;display:grid;gap:2px}
.rail a{
  display:flex;align-items:center;gap:8px;height:44px;
  font:400 .62rem/1 var(--mono);letter-spacing:.1em;color:var(--muted);
  transition:color .18s;
}
.rail a span{font-variant-numeric:tabular-nums}
.rail a i{display:block;width:10px;height:var(--rule);background:currentColor;opacity:.4;transition:width .22s,opacity .22s}
.rail a:hover,.rail a[aria-current="true"]{color:var(--ink)}
.rail a[aria-current="true"] i{width:24px;opacity:1;background:var(--red)}

/* ---------- hero ---------- */
.hero{padding-block:46px 34px;position:relative}
.hero::before{
  content:"";position:absolute;left:-22px;top:0;bottom:0;width:var(--rule);
  background:linear-gradient(var(--red) 0 34%, transparent 34%);
  opacity:.55;
}
.hero-grid{display:grid;grid-template-columns:minmax(0,1fr);gap:34px;align-items:start}
.hero-copy{position:relative}
.hero h1 em{font-style:italic;color:var(--blue)}
.mark{position:relative;display:inline-block;z-index:0}
.mark::after{
  content:"";position:absolute;z-index:-1;left:-.06em;right:-.1em;bottom:.07em;height:.42em;
  background:var(--red-soft);
  transform:rotate(-1.1deg) skewX(-8deg);
  border-radius:1px;
}
.hero .lede{margin-top:20px}
.hero-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:26px}
.hero-stats{
  display:flex;flex-wrap:wrap;gap:0;margin-top:34px;
  border-top:var(--rule) solid var(--line);border-bottom:var(--rule) solid var(--line);
}
.hero-stats div{padding:14px 20px 14px 0;margin-right:20px;border-right:var(--rule) solid var(--line)}
.hero-stats div:last-child{border-right:0}
.hero-stats b{display:block;font:500 1.7rem/1 var(--display);letter-spacing:-.03em}
.hero-stats small{display:block;margin-top:4px;font:400 .62rem/1.3 var(--mono);letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}

/* horario: tarjeta con esquinas marcadas */
.schedule{
  position:relative;background:var(--surface);border:var(--rule) solid var(--line-2);
  border-radius:var(--radius);box-shadow:var(--shadow);
  padding:20px 20px 16px;
}
.schedule::before,.schedule::after{
  content:"";position:absolute;width:14px;height:14px;border:var(--rule) solid var(--ink);
}
.schedule::before{top:-1px;left:-1px;border-right:0;border-bottom:0}
.schedule::after{bottom:-1px;right:-1px;border-left:0;border-top:0}
.schedule-head{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin-bottom:14px}
.schedule-head h2{font-size:1.06rem;letter-spacing:-.01em}
.schedule-head span{font:400 .6rem/1 var(--mono);letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}
.schedule ol{list-style:none;margin:0;padding:0}
.schedule li{
  display:grid;grid-template-columns:52px minmax(0,1fr) auto;gap:10px;align-items:baseline;
  padding:11px 0;border-top:var(--rule) solid var(--line);
}
.schedule li:first-child{border-top:0}
.schedule time{font:400 .68rem/1 var(--mono);color:var(--red);letter-spacing:.02em}
.schedule strong{font-weight:600;font-size:.92rem;line-height:1.3}
.schedule em{font:400 .64rem/1.3 var(--mono);font-style:normal;color:var(--muted);text-align:right}
.schedule-foot{
  display:flex;align-items:center;gap:8px;margin-top:14px;padding-top:12px;
  border-top:var(--rule) dashed var(--line-2);
  font:400 .68rem/1.35 var(--mono);color:var(--muted);
}
.schedule-foot .dot{width:7px;height:7px;border-radius:50%;background:var(--red);flex:none}
/* sello girado */
.seal{
  position:absolute;right:-14px;top:-26px;width:92px;height:92px;
  transform:rotate(-9deg);color:var(--blue);opacity:.92;
  pointer-events:none;
}
.seal text{font:700 10px var(--mono);letter-spacing:.14em;fill:currentColor}
.seal circle{fill:none;stroke:currentColor;stroke-width:1}
.seal .star{fill:currentColor;stroke:none}

/* ---------- banda diagonal de materias ---------- */
.band{
  position:relative;margin-block:30px 12px;
  background:var(--blue);color:var(--paper);
  transform:rotate(-1.15deg) scale(1.03);
  overflow:hidden;
}
.band-track{display:flex;gap:0;width:max-content;animation:slide 34s linear infinite}
.band:hover .band-track{animation-play-state:paused}
.band span{
  display:inline-flex;align-items:center;gap:22px;padding:13px 22px;
  font:400 .74rem/1 var(--mono);letter-spacing:.16em;text-transform:uppercase;white-space:nowrap;
}
.band span::after{content:"✳";color:var(--gold);font-size:1rem;letter-spacing:0}
@keyframes slide{to{transform:translateX(-50%)}}

/* ---------- secciones ---------- */
.section{padding-block:58px;border-top:var(--rule) solid var(--line)}
.section-head{display:grid;grid-template-columns:minmax(0,1fr);gap:16px;margin-bottom:32px}
.section-head .note{color:var(--muted);font-size:.92rem;max-width:38ch}
.section-head .note b{color:var(--ink);font-weight:600}
.head-row{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;flex-wrap:wrap}
.rule-orn{display:flex;align-items:center;gap:10px;color:var(--line-2)}
.rule-orn::before,.rule-orn::after{content:"";height:var(--rule);background:currentColor;flex:1}

/* programa */
.tabs{display:flex;gap:0;border-bottom:var(--rule) solid var(--line-2);margin-bottom:4px;flex-wrap:wrap}
.tab{
  min-height:44px;padding:0 16px 0 0;margin-right:8px;
  font:400 .7rem/1 var(--mono);letter-spacing:.1em;text-transform:uppercase;color:var(--muted);
  border-bottom:2px solid transparent;margin-bottom:-1px;transition:color .18s,border-color .18s;
}
.tab:hover{color:var(--ink)}
.tab[aria-selected="true"]{color:var(--ink);border-color:var(--red)}
.program{list-style:none;margin:0;padding:0}
.program li{border-bottom:var(--rule) solid var(--line)}
.program-row{
  display:grid;grid-template-columns:46px minmax(0,1fr) auto;
  gap:6px 16px;align-items:baseline;padding:20px 14px 20px 6px;
  transition:background .2s,color .2s,padding .2s;
}
.program-row:hover{background:var(--ink);color:var(--paper);padding-left:16px}
.program-row:hover .num,.program-row:hover .meta,.program-row:hover .desc{color:var(--paper-2)}
.program-row:hover .arrow{transform:translate(4px,-4px);color:var(--gold)}
.num{font:400 .72rem/1 var(--mono);color:var(--red);letter-spacing:.06em;font-variant-numeric:tabular-nums}
.program h3{font-size:1.2rem}
.desc{margin-top:5px;font-size:.9rem;line-height:1.5;color:var(--muted);max-width:52ch}
.meta{font:400 .64rem/1.4 var(--mono);letter-spacing:.06em;text-transform:uppercase;color:var(--muted);text-align:right;white-space:nowrap}
.arrow{grid-column:3;justify-self:end;align-self:center;width:20px;height:20px;color:var(--line-2);transition:transform .22s,color .22s}
.program li[hidden]{display:none}

/* pasos */
.steps{display:grid;grid-template-columns:minmax(0,1fr);gap:0;border-top:var(--rule) solid var(--line-2)}
.step{position:relative;padding:26px 0 26px 0;border-bottom:var(--rule) solid var(--line)}
.step-num{
  font:500 clamp(3rem,7vw,4.6rem)/.9 var(--display);letter-spacing:-.06em;
  color:transparent;-webkit-text-stroke:1px var(--line-2);
}
.step:hover .step-num{-webkit-text-stroke-color:var(--red)}
.step h3{margin-top:6px}
.step p{margin-top:8px;color:var(--muted);font-size:.93rem;max-width:34ch}
.step .tag{
  position:absolute;right:0;top:26px;font:400 .6rem/1 var(--mono);letter-spacing:.12em;
  text-transform:uppercase;color:var(--muted);border:var(--rule) solid var(--line);
  padding:6px 8px;border-radius:var(--radius);
}
.step:last-child{border-bottom:0}

/* docentes */
.teachers{display:flex;gap:16px;overflow-x:auto;padding-bottom:12px;scroll-snap-type:x mandatory}
.teacher{flex:0 0 232px;scroll-snap-align:start}
.portrait{
  position:relative;aspect-ratio:3/4;border:var(--rule) solid var(--line-2);
  background:var(--paper-2);overflow:hidden;
}
.portrait svg{display:block;width:100%;height:100%}
.portrait::after{
  content:"";position:absolute;inset:0;
  background:repeating-linear-gradient(0deg, rgba(16,24,39,.05) 0 1px, transparent 1px 4px);
  mix-blend-mode:multiply;pointer-events:none;
}
.portrait .idx{
  position:absolute;left:8px;top:8px;z-index:1;
  font:400 .6rem/1 var(--mono);letter-spacing:.1em;color:var(--paper);
  background:var(--ink);padding:4px 6px;
}
.teacher h3{margin-top:12px;font-size:1.05rem}
.teacher .role{margin-top:3px;font:400 .62rem/1.4 var(--mono);letter-spacing:.08em;text-transform:uppercase;color:var(--red)}
.teacher .bio{margin-top:8px;font-size:.86rem;line-height:1.5;color:var(--muted)}

/* cita */
.quote{position:relative;padding-block:64px 54px;border-top:var(--rule) solid var(--line);overflow:hidden}
.quote::before{
  content:"“";position:absolute;left:-18px;top:-6px;
  font:500 18rem/1 var(--display);color:var(--paper-2);pointer-events:none;
}
.quote blockquote{margin:0;position:relative;max-width:660px}
.quote blockquote p{
  font:400 clamp(1.5rem,3.4vw,2.5rem)/1.2 var(--display);letter-spacing:-.02em;
}
.quote blockquote em{font-style:italic;color:var(--blue)}
.quote-foot{display:flex;align-items:center;gap:14px;margin-top:26px;flex-wrap:wrap}
.quote-foot .who{font:400 .7rem/1.5 var(--mono);letter-spacing:.06em;color:var(--muted)}
.quote-foot .who b{display:block;color:var(--ink);letter-spacing:.02em}
.mini-quotes{display:grid;gap:0;margin-top:36px;border-top:var(--rule) solid var(--line)}
.mini-quotes figure{margin:0;padding:16px 0;border-bottom:var(--rule) solid var(--line);display:grid;gap:6px}
.mini-quotes q{font-size:.9rem;line-height:1.5;quotes:none}
.mini-quotes figcaption{font:400 .62rem/1 var(--mono);letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}

/* admisión: libro contable */
.ledger{display:grid;grid-template-columns:minmax(0,1fr);gap:0;border:var(--rule) solid var(--line-2);background:var(--surface)}
.ledger-head{
  display:flex;align-items:baseline;justify-content:space-between;gap:12px;
  padding:18px 20px;border-bottom:var(--rule) solid var(--line);
}
.ledger-head h3{font-size:1.3rem}
.ledger-head .price{font:500 1.5rem/1 var(--display);letter-spacing:-.03em;white-space:nowrap}
.ledger-head .price small{font:400 .6rem/1 var(--mono);color:var(--muted);letter-spacing:.08em;display:block;margin-top:5px;text-align:right}
.ledger ul{list-style:none;margin:0;padding:0}
.ledger li{
  display:grid;grid-template-columns:18px minmax(0,1fr) auto;gap:10px;align-items:center;
  padding:12px 20px;border-bottom:var(--rule) dashed var(--line);font-size:.9rem;
}
.ledger li:last-child{border-bottom:0}
.ledger li svg{color:var(--red)}
.ledger li .val{font:400 .68rem/1 var(--mono);color:var(--ink-2)}
.ledger-foot{padding:18px 20px;border-top:var(--rule) solid var(--line)}
.ledger-foot .btn{width:100%}
.ledger-note{margin-top:10px;font:400 .62rem/1.5 var(--mono);color:var(--muted);text-align:center}
.ledger.featured{border-color:var(--ink);box-shadow:var(--shadow);position:relative}
.ledger.featured .ledger-head{background:var(--ink);color:var(--paper);border-bottom-color:var(--ink)}
.ledger.featured .ledger-head .price small{color:var(--paper-2)}
.ledger.featured .ledger-foot{background:var(--paper-2)}
.badge-stamp{
  position:absolute;right:14px;top:-16px;transform:rotate(6deg);
  background:var(--red);color:var(--on-red);padding:6px 10px;
  font:700 .58rem/1 var(--mono);letter-spacing:.14em;text-transform:uppercase;
}
.admission-grid{display:grid;grid-template-columns:minmax(0,1fr);gap:26px}

/* faq */
.faq{border-top:var(--rule) solid var(--line-2)}
.faq details{border-bottom:var(--rule) solid var(--line)}
.faq summary{
  display:flex;align-items:center;gap:14px;min-height:56px;padding:14px 4px;
  cursor:pointer;list-style:none;font-weight:600;font-size:.97rem;
}
.faq summary::-webkit-details-marker{display:none}
.faq summary .n{font:400 .64rem/1 var(--mono);color:var(--red);letter-spacing:.06em}
.faq summary .plus{margin-left:auto;width:20px;height:20px;color:var(--line-2);transition:transform .24s,color .24s;flex:none}
.faq details[open] summary .plus{transform:rotate(45deg);color:var(--red)}
.faq details p{padding:0 4px 18px 34px;color:var(--muted);font-size:.92rem;max-width:62ch}

/* cierre */
.close{padding-block:70px;background:var(--ink);color:var(--paper);position:relative;overflow:hidden}
.close::before{
  content:"2026";position:absolute;right:-10px;bottom:-58px;
  font:500 13rem/1 var(--display);letter-spacing:-.06em;color:rgba(245,241,230,.06);
  pointer-events:none;
}
.close h2{max-width:18ch}
.close .lede{color:var(--paper-2);margin-top:16px}
.close-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:26px}
.close .btn-ghost{border-color:var(--paper-2);color:var(--paper)}
.close .btn-ghost:hover{background:var(--paper);color:var(--ink)}
.close .btn-solid{background:var(--red);border-color:var(--red)}
.close-meta{display:flex;gap:26px;flex-wrap:wrap;margin-top:40px;padding-top:20px;border-top:var(--rule) solid rgba(245,241,230,.22);font:400 .64rem/1.6 var(--mono);letter-spacing:.08em;text-transform:uppercase;color:var(--paper-2)}

/* pie */
.foot{padding-block:36px 90px;border-top:var(--rule) solid var(--line)}
.foot-grid{display:grid;grid-template-columns:minmax(0,1fr);gap:26px}
.foot .brand{font-size:1.5rem}
.foot p{margin-top:10px;color:var(--muted);font-size:.86rem;max-width:32ch}
.foot nav{display:grid;gap:2px;font-size:.88rem;color:var(--ink-2)}
.foot nav b{font:400 .6rem/1 var(--mono);letter-spacing:.14em;text-transform:uppercase;color:var(--muted);margin-bottom:4px}
.foot nav a{display:inline-flex;align-items:center;min-height:44px}
.foot nav a:hover{color:var(--red)}
.foot-legal{margin-top:34px;padding-top:16px;border-top:var(--rule) solid var(--line);display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;font:400 .6rem/1.5 var(--mono);letter-spacing:.06em;color:var(--muted)}

/* barra inferior móvil */
.bottom{display:none}

/* entrada de portada (una sola, no fade-up en todo el sitio) */
@keyframes intro{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
.hero-copy{animation:intro .5s ease both}
.schedule{animation:intro .55s .08s ease both}
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *,*::before,*::after{animation-duration:.001ms!important;animation-iteration-count:1!important;transition-duration:.001ms!important}
  .hero-copy,.schedule{animation:none}
}

/* ---------- escritorio ---------- */
@media (min-width:860px){
  .nav{display:flex}
  .top-cta{display:inline-flex}
  .menu-btn{display:none}
  .menu{display:none!important}
  .shell{grid-template-columns:96px minmax(0,1fr)}
  .rail{display:block}
  .hero-grid{grid-template-columns:minmax(0,1.32fr) minmax(300px,.78fr);gap:40px}
  .section-head{grid-template-columns:minmax(0,1.4fr) minmax(0,.6fr);align-items:end;gap:32px}
  .steps{grid-template-columns:repeat(3,minmax(0,1fr));border-bottom:var(--rule) solid var(--line)}
  .step{padding:28px 24px 30px 0;border-bottom:0;border-right:var(--rule) solid var(--line)}
  .step:last-child{border-right:0;padding-right:0}
  .step + .step{padding-left:24px}
  .admission-grid{grid-template-columns:minmax(0,1.15fr) minmax(300px,.85fr);gap:32px;align-items:start}
  .ledger.featured{margin-top:-12px}
  .mini-quotes{grid-template-columns:repeat(2,minmax(0,1fr));column-gap:40px;border-top:0}
  .mini-quotes figure:nth-child(1){border-top:var(--rule) solid var(--line)}
  .mini-quotes figure:nth-child(2){border-top:var(--rule) solid var(--line)}
  .foot-grid{grid-template-columns:minmax(0,1.4fr) repeat(2,minmax(0,.5fr))}
  .foot{padding-bottom:40px}
}
@media (min-width:1100px){
  .quote{padding-left:0}
  .quote blockquote{margin-left:6%}
  .quote-foot{margin-left:6%}
}

/* ---------- móvil (390px pensado, no encogido) ---------- */
@media (max-width:859px){
  body{font-size:15.5px}
  .shell{grid-template-columns:minmax(0,1fr)}
  .hero{padding-block:30px 26px}
  .hero::before{display:none}
  h1{font-size:clamp(2.3rem,10.4vw,3.1rem);line-height:1.02}
  .hero-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0}
  .hero-stats div{padding:12px 10px 12px 0;margin-right:0;border-right:var(--rule) solid var(--line)}
  .hero-stats div:nth-child(3){border-right:0;padding-left:10px}
  .hero-stats b{font-size:1.34rem}
  .hero-stats small{font-size:.54rem;letter-spacing:.06em}
  .schedule-head span{display:none}
  .seal{width:74px;height:74px;right:-6px;top:-20px}
  .band{transform:rotate(-1.6deg) scale(1.06);margin-block:22px 6px}
  .band span{padding:11px 16px;font-size:.68rem;gap:16px}
  .section{padding-block:42px}
  .section-head{margin-bottom:24px}
  .program-row{grid-template-columns:38px minmax(0,1fr);padding:18px 8px 18px 2px}
  .program-row .meta{grid-column:2;text-align:left;margin-top:6px}
  .program-row .arrow{display:none}
  .step-num{font-size:3.2rem}
  .step .tag{top:24px}
  .quote{padding-block:52px 40px}
  .quote::before{font-size:11rem;left:-10px;top:6px}
  .quote blockquote{max-width:100%}
  .close{padding-block:52px}
  .close::before{font-size:8rem;bottom:-34px}
  .foot{padding-bottom:96px}
  .bottom{
    display:grid;grid-template-columns:repeat(4,1fr);position:fixed;left:0;right:0;bottom:0;z-index:50;
    background:color-mix(in srgb,var(--surface) 94%,transparent);backdrop-filter:blur(10px);
    border-top:var(--rule) solid var(--line-2);
    padding-bottom:env(safe-area-inset-bottom,0px);
  }
  .bottom a{
    display:grid;justify-items:center;gap:4px;min-height:56px;padding:9px 4px 7px;
    font:400 .58rem/1 var(--mono);letter-spacing:.08em;text-transform:uppercase;color:var(--muted);
  }
  .bottom a[aria-current="page"]{color:var(--red)}
  .bottom .i{width:20px;height:20px}
}

