(function(){
  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* cabecera + progreso de lectura */
  var head = document.querySelector('.head');
  var bar = document.querySelector('.progress i');
  function onScroll(){
    head.classList.toggle('is-stuck', window.scrollY > 24);
    var h = document.documentElement.scrollHeight - window.innerHeight;
    bar.style.width = (h > 0 ? (window.scrollY / h) * 100 : 0) + '%';
    stepsFill();
  }
  window.addEventListener('scroll', onScroll, {passive:true});
  onScroll();

  /* revelado */
  var io = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if (e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); }
    });
  }, {threshold:.04, rootMargin:'0px 0px -2% 0px'});
  document.querySelectorAll('.reveal').forEach(function(el){ io.observe(el); });

  /* contadores */
  var counted = new WeakSet();
  var cio = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if (!e.isIntersecting || counted.has(e.target)) return;
      counted.add(e.target);
      var el = e.target, target = parseInt(el.dataset.count, 10), start = null;
      if (reduce){ el.textContent = target; return; }
      function tick(t){
        if (!start) start = t;
        var p = Math.min((t - start) / 1300, 1);
        el.textContent = Math.round(target * (1 - Math.pow(1 - p, 3)));
        if (p < 1) requestAnimationFrame(tick);
      }
      requestAnimationFrame(tick);
    });
  }, {threshold:.6});
  document.querySelectorAll('[data-count]').forEach(function(el){ cio.observe(el); });

  /* timeline */
  var steps = document.getElementById('steps');
  var fill = steps.querySelector('.fill');
  function stepsFill(){
    if (!steps || !fill) return;
    var r = steps.getBoundingClientRect();
    var p = (window.innerHeight * .62 - r.top) / r.height;
    fill.style.height = Math.max(0, Math.min(1, p)) * 100 + '%';
  }
  stepsFill();

  /* cursor */
  var cursor = document.querySelector('.cursor');
  if (cursor && !reduce){
    var cx = 0, cy = 0, tx = 0, ty = 0;
    window.addEventListener('pointermove', function(e){
      tx = e.clientX; ty = e.clientY;
      cursor.classList.toggle('is-hot', !!e.target.closest('a,button,.row,.proj'));
    }, {passive:true});
    (function loop(){
      cx += (tx - cx) * .18; cy += (ty - cy) * .18;
      cursor.style.transform = 'translate(' + cx + 'px,' + cy + 'px) translate(-50%,-50%)';
      requestAnimationFrame(loop);
    })();
  }

  /* testimonios */
  var quotes = [
    {t:'Pasamos de parecer una pyme a parecer <span>la categoría</span>.', a:'Lucía Ferrer · Directora, Órbita Energía'},
    {t:'El sistema que dejaron sigue vivo <span>dos años después</span>.', a:'Mateo Ruiz · Head of Product, Nudo Banco'},
    {t:'Menos piezas, mejor pensadas. <span>Se nota</span> en cada pantalla.', a:'Sofía Amaral · Editora, Faro Editorial'}
  ];
  var qi = 0, qText = document.getElementById('quote-text'), qAuthor = document.getElementById('quote-author');
  var dots = Array.prototype.slice.call(document.querySelectorAll('.quote .dots button'));
  var timer;
  function setQuote(i){
    qi = i;
    qText.style.opacity = 0;
    setTimeout(function(){
      qText.innerHTML = quotes[i].t;
      qAuthor.textContent = quotes[i].a;
      qText.style.transition = 'opacity .45s cubic-bezier(.22,1,.36,1)';
      qText.style.opacity = 1;
    }, reduce ? 0 : 220);
    dots.forEach(function(d, k){ d.setAttribute('aria-current', String(k === i)); });
  }
  dots.forEach(function(d, i){
    d.addEventListener('click', function(){ clearInterval(timer); setQuote(i); });
  });
  if (!reduce) timer = setInterval(function(){ setQuote((qi + 1) % quotes.length); }, 7000);

  /* botón magnético */
  document.querySelectorAll('.btn').forEach(function(btn){
    if (reduce) return;
    btn.addEventListener('pointermove', function(e){
      var r = btn.getBoundingClientRect();
      var dx = (e.clientX - r.left - r.width / 2) / r.width;
      var dy = (e.clientY - r.top - r.height / 2) / r.height;
      btn.style.transform = 'translate(' + (dx * 6).toFixed(1) + 'px,' + (dy * 4).toFixed(1) + 'px)';
    });
    btn.addEventListener('pointerleave', function(){ btn.style.transform = ''; });
  });

  /* menú móvil: ancla al primer destino */
  var burger = document.querySelector('.burger');
  if (burger) burger.addEventListener('click', function(){
    document.getElementById('servicios').scrollIntoView({behavior: reduce ? 'auto' : 'smooth'});
  });
})();
